<?php
require __DIR__ . '/bootstrap.php';
bitsy_admin_require_login();
bitsy_admin_mark_seen('pages');
$navCounts = bitsy_admin_new_counts();
$message = '';
$error = '';
if (isset($_GET['saved'])) { $message = 'Page content and SEO details saved.'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!bitsy_admin_check_csrf(isset($_POST['csrf']) ? $_POST['csrf'] : '')) { http_response_code(403); exit('Invalid request.'); }
  $file = bitsy_admin_find_page(isset($_POST['slug']) ? $_POST['slug'] : '');
  $metaSaved = $file && bitsy_admin_update_meta($file, isset($_POST['title']) ? $_POST['title'] : '', isset($_POST['description']) ? $_POST['description'] : '');
  $contentSaved = $file && bitsy_admin_update_page_content($file, isset($_POST['heading']) ? $_POST['heading'] : '', isset($_POST['intro']) ? $_POST['intro'] : '');
  if ($metaSaved && $contentSaved) { header('Location: pages.php?saved=1'); exit; } else { $error = 'The page could not be updated.'; }
}
$pages = bitsy_admin_pages();
foreach ($pages as &$page) {
  $content = bitsy_admin_page_content($page['file']);
  if (!isset($page['heading']) || $page['heading'] === '') { $page['heading'] = $content['heading']; }
  if (!isset($page['intro']) || $page['intro'] === '') { $page['intro'] = $content['intro']; }
}
unset($page);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pages | Bitsy Admin</title><link rel="stylesheet" href="assets/admin.css"></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><img class="brand-mark" src="../assets/img/bitsy-favicon.png" alt="Bitsy AV"><span>Bitsy <small>Admin</small></span></a><p class="nav-label">Workspace</p><nav class="side-nav"><a href="index.php"><span></span>Dashboard</a><a class="active" href="pages.php"><span></span>Pages</a><a href="posts.php"><span></span>Posts<?php if ($navCounts['posts'] > 0): ?> <b><?php echo $navCounts['posts']; ?></b><?php endif; ?></a><a href="categories.php"><span></span>Categories<?php if ($navCounts['categories'] > 0): ?> <b><?php echo $navCounts['categories']; ?></b><?php endif; ?></a><a href="media.php"><span></span>Media</a><a href="leads.php"><span></span>Enquiries</a></nav><p class="nav-label">System</p><nav class="side-nav"><a href="../" target="_blank"><span></span>View website</a><?php if (bitsy_admin_is_admin()): ?><a href="snippets.php"><span></span>Code Snippets</a><a href="users.php"><span></span>Users</a><?php endif; ?><a href="logout.php"><span></span>Sign out</a></nav></aside><div class="admin-content"><header class="topbar"><div><p class="eyebrow">CONTENT / PAGES</p><h1>Pages</h1></div><a class="avatar" href="logout.php">A</a></header><main class="admin-main"><div class="page-toolbar"><p class="muted">Edit the main page message and search preview for each live page.</p><a class="button primary" href="../index.php" target="_blank">View website -&gt;</a></div><?php if ($message): ?><p class="alert success"><?php echo bitsy_admin_escape($message); ?></p><?php endif; ?><?php if ($error): ?><p class="alert error"><?php echo bitsy_admin_escape($error); ?></p><?php endif; ?><section class="panel page-table"><div class="table-tools"><strong>All pages <span class="muted"><?php echo count($pages); ?></span></strong><span class="table-note">Edits publish directly to the PHP page</span></div><div class="table-wrap"><table><thead><tr><th>Page</th><th>Status</th><th>Page content</th><th>SEO</th><th>Actions</th></tr></thead><tbody><?php foreach ($pages as $page): ?><tr id="<?php echo bitsy_admin_escape($page['slug']); ?>"><td><div class="page-cell"><span class="file-icon">P</span><div><strong><?php echo bitsy_admin_escape(ucwords(str_replace('-', ' ', $page['slug']))); ?></strong><small>/<?php echo bitsy_admin_escape($page['slug']); ?>.php</small></div></div></td><td><span class="status published">Published</span></td><td class="truncate"><?php echo bitsy_admin_escape($page['heading']); ?><small><?php echo bitsy_admin_escape($page['intro']); ?></small></td><td><span class="status <?php echo ($page['title'] && $page['description']) ? 'published' : 'draft'; ?>"><?php echo ($page['title'] && $page['description']) ? 'SEO ready' : 'Needs SEO'; ?></span></td><td><a class="row-action" href="#edit-<?php echo bitsy_admin_escape($page['slug']); ?>">Edit page</a></td></tr><tr class="edit-row" id="edit-<?php echo bitsy_admin_escape($page['slug']); ?>"><td colspan="5"><form method="post" class="seo-form content-editor"><input type="hidden" name="csrf" value="<?php echo bitsy_admin_escape(bitsy_admin_csrf()); ?>"><input type="hidden" name="slug" value="<?php echo bitsy_admin_escape($page['slug']); ?>"><label>Main heading<input name="heading" value="<?php echo bitsy_admin_escape($page['heading']); ?>" maxlength="240" required></label><label>Intro paragraph<textarea name="intro" rows="3" maxlength="600" required><?php echo bitsy_admin_escape($page['intro']); ?></textarea></label><label>SEO title<input name="title" value="<?php echo bitsy_admin_escape($page['title']); ?>" maxlength="160" required></label><label>Meta description<textarea name="description" rows="3" maxlength="320" required><?php echo bitsy_admin_escape($page['description']); ?></textarea></label><div class="edit-actions"><a href="#<?php echo bitsy_admin_escape($page['slug']); ?>" class="close-editor">Close</a><a href="../<?php echo bitsy_admin_escape($page['slug']); ?>.php" target="_blank">Preview -&gt;</a><button class="button primary" type="submit">Save page</button></div></form></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></div></body></html>